package handlers.skill.conditions;

import org.l2jmobius.gameserver.entity.WorldObject;
import org.l2jmobius.gameserver.entity.actor.Creature;
import org.l2jmobius.gameserver.mechanics.skill.ISkillCondition;
import org.l2jmobius.gameserver.mechanics.skill.Skill;
import org.l2jmobius.gameserver.util.StatSet;

/**
 * Checks if the player has learned a specific skill from an Agathion.<br>
 * This condition is used to verify required skills for certain actions.
 * @author Sdw
 */
public class OpNeedAgathionSkillCondition implements ISkillCondition
{
	/**
	 * Creates a new condition for skills that require specific stats.<br>
	 * This constructor initializes the requirements using a {@code StatSet}.
	 * @param params The set of statistics required to use the skill.
	 */
	public OpNeedAgathionSkillCondition(StatSet params)
	{
	}
	
	/**
	 * Checks if the {@code caster} is allowed to use a specific {@code skill}.<br>
	 * This method verifies that the {@code caster} is a player.<br>
	 * It also checks if the player has a valid Agathion ID assigned.
	 * @param caster The {@code Creature} attempting to cast the skill.
	 * @param skill The {@code Skill} being used.
	 * @param target The {@code WorldObject} targeted by the skill.
	 * @return {@code true} if all conditions are met, otherwise {@code false}.
	 */
	@Override
	public boolean canUse(Creature caster, Skill skill, WorldObject target)
	{
		return caster.isPlayer() && (caster.asPlayer().getAgathionId() != 0);
	}
}
